// Reference vectors of TTE2 (internal/tte2/testdata/vectors.json, generated by the Go reference):
// every file, size, metadata and message vector, positive and negative, checked in both directions.
// The validator vectors exercise the server's keyless Validator, which has no browser counterpart.

import { describe, expect, it } from 'vitest';
import vectors from '../../../../internal/tte2/testdata/vectors.json';
import { createDecryptStream, decryptBytes } from './decrypt';
import {
  openMessage,
  openMetadata,
  sealMessage,
  sealMetadata,
  sealMetadataRaw,
  encodeMetadata,
} from './sealed';
import {
  ciphertextSize,
  encodeKey,
  encryptRange,
  importTransferKey,
  newHeader,
  deriveFileKey,
  parseKey,
  plaintextSize,
  prepareFileEncryption,
  validSize,
} from './tte2';
import {
  fromBase64,
  firstDifference,
  fromHex,
  goErrorName,
  pattern,
  pipe,
  seededRandom,
  sha256Hex,
  split,
} from './tte2-helpers.test-helper';

/** A piece of a constructed input: a slice of a file vector or literal bytes. */
interface Part {
  base?: string;
  from?: number;
  to?: number;
  hex?: string;
}

const key = fromHex(vectors.keyHex);
const streams = new Map<string, Uint8Array<ArrayBuffer>>(
  vectors.files.map((f) => [f.name, fromBase64(f.ciphertextBase64)]),
);

/** Concatenates the parts of a constructed input (omitted from/to are 0, as in Go; null is none). */
function build(parts: Part[] | null): Uint8Array<ArrayBuffer> {
  const pieces = (parts ?? []).map((p) =>
    p.base === undefined ? fromHex(p.hex ?? '') : streams.get(p.base)!.slice(p.from ?? 0, p.to ?? 0),
  );
  const out = new Uint8Array(pieces.reduce((n, p) => n + p.length, 0));
  let o = 0;
  for (const p of pieces) {
    out.set(p, o);
    o += p.length;
  }
  return out;
}

/** The key of a case: its override or the vector key. */
function keyFor(c: { keyHex?: string }): Uint8Array<ArrayBuffer> {
  return c.keyHex === undefined ? key : fromHex(c.keyHex);
}

it('decodes and encodes the key fragment', () => {
  expect(parseKey(vectors.keyFragment)).toEqual(key);
  expect(encodeKey(key)).toBe(vectors.keyFragment);
});

describe('file vectors', () => {
  for (const f of vectors.files) {
    it(`${f.name}: encrypts to the reference bytes and decrypts back`, async () => {
      const ct = streams.get(f.name)!;
      expect(ct.length).toBe(f.ciphertextLength);
      expect(await sha256Hex(ct)).toBe(f.ciphertextSha256Hex);
      const plain = pattern(f.plaintextLength);
      expect(await sha256Hex(plain)).toBe(f.plaintextSha256Hex);
      expect(ciphertextSize(f.plaintextLength, f.chunkSize)).toBe(ct.length);
      expect(plaintextSize(ct.length, f.chunkSize)).toBe(f.plaintextLength);

      const salt = fromHex(f.saltHex);
      const header = newHeader(f.chunkSize, salt);
      const fileKey = await deriveFileKey(key, salt, f.index);
      const blob = new Blob([plain]);
      expect(firstDifference(await encryptRange(fileKey, header, blob, plain.length, 0, ct.length), ct)).toBe(
        -1,
      );

      const base = await importTransferKey(key);
      const enc = await prepareFileEncryption(base, f.index, blob, { chunkSize: f.chunkSize, salt });
      expect(enc.size).toBe(ct.length);
      expect(firstDifference(await enc.range(0, enc.size), ct)).toBe(-1);

      expect(firstDifference(await decryptBytes({ key, index: f.index }, ct), plain)).toBe(-1);
      const rand = seededRandom(f.index + 1);
      const out = await pipe(createDecryptStream({ key: base, index: f.index }), split(ct, rand, 9000));
      expect(firstDifference(out, plain)).toBe(-1);
    });
  }
});

describe('file negative vectors', () => {
  for (const c of vectors.fileNegative) {
    it(`${c.name}: ${c.expectedError}`, async () => {
      const input = build(c.parts);
      const source = { key: keyFor(c), index: c.index };
      expect(await goErrorName(() => decryptBytes(source, input))).toBe(c.expectedError);
      const pieces = split(input, seededRandom(input.length), 5000);
      expect(await goErrorName(() => pipe(createDecryptStream(source), pieces))).toBe(c.expectedError);
    });
  }
});

it('size vectors', () => {
  for (const s of vectors.sizes) {
    const p = plaintextSize(s.total, s.chunkSize);
    expect(validSize(s.total, s.chunkSize), JSON.stringify(s)).toBe(s.valid);
    expect(p, JSON.stringify(s)).toBe(s.valid ? s.plaintext : -1);
    if (s.valid) expect(ciphertextSize(p, s.chunkSize)).toBe(s.total);
  }
});

describe('metadata vectors', () => {
  for (const m of vectors.metadata) {
    it(`${m.name}: seals to the reference blob and opens back`, async () => {
      const nonce = fromHex(m.nonceHex);
      const { v, ...fields } = m.metadata;
      expect(v).toBe(1);
      const want = { path: '', ...fields };
      expect(encodeMetadata(want)).toBe(m.plaintext);
      expect(await sealMetadata(key, m.index, want, { nonce })).toBe(m.sealed);
      const raw = new TextEncoder().encode(m.plaintext);
      expect(await sealMetadataRaw(await importTransferKey(key), m.index, raw, { nonce })).toBe(m.sealed);
      expect(await openMetadata(key, m.index, m.sealed)).toEqual(want);
    });
  }
  for (const c of vectors.metadataNegative) {
    it(`negative ${c.name}: ${c.expectedError}`, async () => {
      expect(await goErrorName(() => openMetadata(keyFor(c), c.index, c.sealed))).toBe(c.expectedError);
    });
  }
});

describe('message vectors', () => {
  for (const m of vectors.messages) {
    it(`${m.name}: seals to the reference blob and opens back`, async () => {
      expect(await sealMessage(key, m.text, { nonce: fromHex(m.nonceHex) })).toBe(m.sealed);
      expect(await openMessage(key, m.sealed)).toBe(m.text);
    });
  }
  for (const c of vectors.messageNegative) {
    it(`negative ${c.name}: ${c.expectedError}`, async () => {
      expect(await goErrorName(() => openMessage(keyFor(c), c.sealed))).toBe(c.expectedError);
    });
  }
});
